namespace ghidra.util.worker;

using ghidra.util.exception;
using ghidra.util.task;

public abstract class Job {

	private volatile bool completed;
	private volatile bool cancelled;
	private volatile Throwable error;
	private volatile TaskMonitor taskMonitor;

	/**
	 * The method that gets called by the Worker when this job is selected to be run
	 * by the Worker.
	 * @param monitor the monitor
	 * @throws CancelledException jobs may choose to throw a cancelled exception
	 */
	public abstract void run(TaskMonitor monitor);

	public bool isCompleted() {
		return completed;
	}

	public void setCompleted() {
		completed = true;
	}

	public bool isCancelled() {
		return cancelled;
	}

	public void setError(Throwable t) {
		this.error = t;
	}

	public bool hasError() {
		return error != null;
	}

	public Throwable getError() {
		return error;
	}

	public void cancel() {
		cancelled = true;
		if (taskMonitor != null) {
			taskMonitor.cancel();
		}
	}

	protected void setTaskMonitor(TaskMonitor monitor) {
		this.taskMonitor = monitor;
	}
}
